// Inactive shadow relay. Verify the WordPress ingress signature,
// normalize a bounded allowlist, then sign the exact host body with a distinct
// relay secret. No execution payload should be retained.
const crypto = require('crypto');
const wrapped = $input.first().json || {};
const headers = wrapped.headers && typeof wrapped.headers === 'object' ? wrapped.headers : {};
const source = wrapped.body && typeof wrapped.body === 'object' && !Array.isArray(wrapped.body) ? wrapped.body : null;
if (!source) throw new Error('invalid_checkout_body');
const ingressSecret = String($env.CHECKOUT_RECOVERY_INGRESS_SECRET || '');
const relaySecret = String($env.CHECKOUT_RECOVERY_RELAY_SECRET || '');
const hostUrl = String($env.CHECKOUT_RECOVERY_HOST_URL || '');
if (ingressSecret.length < 32) throw new Error('ingress_secret_unconfigured');
if (relaySecret.length < 32 || relaySecret === ingressSecret) throw new Error('relay_secret_unconfigured');
if (!/^https?:\/\//.test(hostUrl)) throw new Error('host_url_unconfigured');
const incomingTimestamp = String(headers['x-checkout-timestamp'] || headers['X-Checkout-Timestamp'] || '');
const incomingSignature = String(headers['x-checkout-signature'] || headers['X-Checkout-Signature'] || '').replace(/^sha256=/, '');
if (!/^\d{10}$/.test(incomingTimestamp) || !/^[0-9a-f]{64}$/.test(incomingSignature)) throw new Error('ingress_signature_missing');
if (Math.abs(Math.floor(Date.now() / 1000) - Number(incomingTimestamp)) > 300) throw new Error('ingress_signature_stale');
const sourceText = JSON.stringify(source);
const expected = crypto.createHmac('sha256', ingressSecret).update(incomingTimestamp + '.' + sourceText, 'utf8').digest('hex');
if (!crypto.timingSafeEqual(Buffer.from(expected, 'hex'), Buffer.from(incomingSignature, 'hex'))) throw new Error('ingress_signature_invalid');
const allowedEvents = new Set(['checkout.captured','payment.created','checkout.client_abandoned','payment.failed','payment.succeeded']);
if (source.schema_version !== 1 || !allowedEvents.has(source.event_type)) throw new Error('unsupported_checkout_event');
const fields = ['schema_version','source_event_key','event_type','observed_at','checkout_token','email','program_slug','product_slug','product_name','amount_cents','currency','consent_state','consent_policy_version','locale','return_url','payment_intent_id','checkout_session_id'];
const normalized = {};
for (const field of fields) if (source[field] !== undefined) normalized[field] = source[field];
const bodyText = JSON.stringify(normalized);
if (Buffer.byteLength(bodyText, 'utf8') > 32768) throw new Error('payload_too_large');
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = 'sha256=' + crypto.createHmac('sha256', relaySecret).update(timestamp + '.' + bodyText, 'utf8').digest('hex');
return [{ json: { host_url: hostUrl, timestamp, signature, body_text: bodyText } }];
